select
  '0577896c-6dcd-597f-9275-cef1b4d11583'::uuid,
  'legislacao-organizacoes-revisao',
  '2026-10-08',
  '4373a524a985df9c9d13fdcbb95abee13feb93a0a27fef8fe7f28834f7037eed',
  $json${"illustrations": [{"kind": "flow", "title": "Como pensar a Lei 12.850", "caption": "Siga as quatro perguntas na ordem; cada caso abaixo trabalha uma delas.", "nodes": ["É organização criminosa? (4+ pessoas, estrutura, divisão de tarefas, crime-fim)", "Quem responde: integrante ou também quem atrapalha a investigação?", "O delator ajudou de verdade? (resultado concreto, art. 4º)", "A infiltração de agente está dentro do prazo?"]}], "cases": [{"id": "org-1", "title": "Quatro pessoas juntas são uma organização criminosa?", "scenario": "Quatro amigos — Ana, Bruno, Caio e Dani — combinam praticar, cada um por conta própria, pequenos golpes contra lojas. Não há chefe, ninguém tem função fixa e o crime que praticam tem pena máxima de 3 anos.", "question": "Eles formam uma organização criminosa pela Lei 12.850?", "steps": ["A lei define organização criminosa como associação de 4 ou mais pessoas, estruturalmente ordenada e com divisão de tarefas, ainda que informal (art. 1º, § 1º). Aqui são 4 pessoas: o primeiro requisito de número está cumprido.", "Falta a estrutura ordenada com divisão de tarefas: cada um age sozinho, sem chefe nem funções. Ter quatro pessoas não basta.", "Falta também o crime-fim: a lei exige infrações com pena máxima superior a 4 anos (ou de caráter transnacional). Neste caso a pena máxima é de 3 anos."], "conclusion": "Não. Quatro pessoas cometendo crimes juntas não formam, por si só, organização criminosa: é preciso estrutura com divisão de tarefas e crimes com pena máxima acima de 4 anos (ou transnacionais). Os crimes que cometerem continuam puníveis, mas pelas regras próprias de cada crime.", "variation": {"scenario": "E se existisse um chefe que recruta, um motorista que leva o grupo, um falsificador e um encarregado de esconder o dinheiro, e o crime-fim tivesse pena máxima de 8 anos?", "answer": "Aí os três elementos aparecem juntos: 4 ou mais pessoas, estrutura com divisão de tarefas (mesmo informal) e crime com pena máxima superior a 4 anos. É organização criminosa."}, "pitfall": "Achar que basta juntar 4 pessoas para ter organização criminosa. Número, estrutura com divisão de tarefas e crime-fim com pena acima de 4 anos (ou transnacional) precisam estar presentes.", "articles": ["Art. 1"]}, {"id": "org-2", "title": "Atrapalhar a investigação sem fazer parte do grupo", "scenario": "Pedro é amigo de um dos integrantes de uma organização criminosa, mas nunca fez parte dela. Ao saber que a polícia investiga o grupo, ele apaga mensagens e esconde documentos para dificultar a investigação.", "question": "Pedro pode ser punido pela Lei 12.850 mesmo sem integrar a organização?", "steps": ["O caput do art. 2º pune quem promove, constitui, financia ou integra a organização, com reclusão de 3 a 8 anos e multa. Pedro não faz parte, então não responde por esse caput.", "O § 1º do mesmo artigo (redação da Lei 15.245/2025) pune com as mesmas penas quem impede ou, de qualquer forma, embaraça a investigação de infração penal que envolva organização criminosa.", "A ressalva é que o § 1º só se aplica se o fato não constituir crime mais grave."], "conclusion": "Sim. Pedro responde pelo § 1º do art. 2º: quem embaraça a investigação de organização criminosa sofre as mesmas penas, mesmo sem ser integrante, desde que o fato não seja crime mais grave.", "variation": {"scenario": "E se, para atrapalhar a investigação, Pedro tivesse cometido um outro crime com pena maior do que a do art. 2º?", "answer": "Responde pelo crime mais grave, porque o próprio § 1º diz que só vale se o fato não constituir crime mais grave."}, "pitfall": "Pensar que a Lei 12.850 só atinge quem integra a organização. O embaraço à investigação também é punido, de fora do grupo.", "articles": ["Art. 2"]}, {"id": "org-3", "title": "Confessar não é colaborar: o que a colaboração premiada exige", "scenario": "Marcos, integrante de uma organização criminosa, é preso e diz aos investigadores: \"Assumo o que fiz, mas só isso\". Ele confirma fatos que a polícia já sabia, não indica outros membros nem diz onde está o dinheiro do grupo, e pede redução de pena por colaboração.", "question": "Marcos tem direito aos benefícios do art. 4º?", "steps": ["A colaboração premiada é um dos meios de obtenção de prova da lei (art. 3º, I). Pode levar a perdão judicial, redução de até 2/3 da pena ou substituição por pena restritiva de direitos.", "Para isso, a colaboração tem de ser efetiva e voluntária e produzir pelo menos um destes resultados (art. 4º): identificar coautores e partícipes e seus crimes; revelar a estrutura hierárquica e a divisão de tarefas; prevenir infrações da organização; recuperar total ou parcialmente o produto ou proveito dos crimes; ou localizar vítima com a integridade física preservada.", "Marcos apenas confirmou o que já se sabia. Nenhum desses resultados apareceu."], "conclusion": "Não. Confessar o próprio crime não é colaboração premiada: a lei exige um resultado concreto e útil para a investigação, e não apenas admitir os fatos.", "variation": {"scenario": "E se Marcos indicasse o endereço de um depósito, até então desconhecido, onde está guardado o produto dos crimes, e a polícia o recuperasse?", "answer": "Aí há um dos resultados do art. 4º (recuperação do produto ou proveito), e a colaboração pode gerar os benefícios, desde que continue efetiva e voluntária."}, "pitfall": "Confundir confissão com colaboração premiada. A colaboração exige resultado concreto previsto em lei, não apenas admitir a culpa.", "articles": ["Art. 3", "Art. 4"]}, {"id": "org-4", "title": "Por quanto tempo um policial pode ficar infiltrado?", "scenario": "A polícia consegue autorização judicial para infiltrar um agente numa organização criminosa. Depois de 8 meses, o delegado quer manter o agente lá, sem pedir nada de novo ao juiz.", "question": "O delegado pode manter a infiltração sem nova decisão?", "steps": ["A lei estabelece que a infiltração é autorizada pelo prazo de até 6 meses, sem prejuízo de renovações, desde que comprovada a necessidade (art. 10, § 3º).", "Seis meses é o prazo de cada autorização. Passou disso, é preciso uma renovação decidida pelo juiz, com a necessidade demonstrada.", "Sem a renovação, a atividade de infiltração deixa de ter autorização para continuar."], "conclusion": "Não. Depois de 6 meses, a continuidade depende de renovação judicial, com comprovação de que a infiltração ainda é necessária.", "variation": {"scenario": "E se, aos 5 meses, o delegado pedisse a renovação e o juiz a concedesse por mais 6 meses, reconhecendo a necessidade?", "answer": "Está correto: a lei permite renovações, desde que haja decisão e comprovação de necessidade em cada uma."}, "pitfall": "Tratar os 6 meses como limite total e improrrogável. O prazo é de cada autorização e pode ser renovado, com decisão fundamentada. Atenção ao número do artigo: a infiltração está no art. 10; o art. 8º trata da ação controlada.", "articles": ["Art. 10"]}]}$json$::jsonb,
